// CompactWithDeletionMarkers performs deletion-mark-aware compaction. It filters out
// blocks that match the provided deletion markers before proceeding with garbage collection.
// This enables Mimir's multi-tenant compactor to pass tenant-specific deletion marks
// so that marked blocks are excluded from compaction planning and treated as candidates
// for removal.
func (s *Syncer) CompactWithDeletionMarkers(ctx context.Context, markers []metadata.DeletionMark) error {
	s.mtx.Lock()

	// Build a lookup set from the provided deletion markers.
	markerSet := make(map[ulid.ULID]metadata.DeletionMark, len(markers))
	for _, m := range markers {
		markerSet[m.ID] = m
	}

	// Remove blocks that are marked for deletion from the syncer's known blocks.
	for id := range s.blocks {
		if _, exists := markerSet[id]; exists {
			delete(s.blocks, id)
		}
	}

	s.mtx.Unlock()

	// Mark blocks for deletion in the bucket if they are not already marked.
	for _, m := range markers {
		if ctx.Err() != nil {
			return ctx.Err()
		}

		delCtx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)

		level.Info(s.logger).Log("msg", "marking block for deletion via deletion marker", "block", m.ID, "details", m.Details)
		err := block.MarkForDeletion(delCtx, s.logger, s.bkt, m.ID, m.Details, s.metrics.BlocksMarkedForDeletion)
		cancel()
		if err != nil {
			return errors.Wrapf(err, "mark block %s for deletion from deletion marker", m.ID)
		}
	}

	return nil
}
